# Token kinds.
_INT = "INT"
_OP = "OP"
_LPAREN = "("
_RPAREN = ")"
_END = "END"

# Longest operators first so that '**' and '//' win over '*' and '/'.
_OPERATORS = ("**", "//", "+", "-", "*", "/", "%")

_DIGITS = "0123456789"


class _Token:
    __slots__ = ("kind", "value", "pos")

    def __init__(self, kind, value, pos):
        self.kind = kind
        self.value = value
        self.pos = pos

    def __repr__(self):  # pragma: no cover - debugging aid only
        return "_Token(%r, %r, %r)" % (self.kind, self.value, self.pos)


def _tokenize(text):
    """Split `text` into tokens, raising ValueError on unknown characters."""
    tokens = []
    i = 0
    n = len(text)
    while i < n:
        ch = text[i]

        # Whitespace between tokens is insignificant.
        if ch.isspace():
            i += 1
            continue

        if ch in _DIGITS:
            start = i
            while i < n and text[i] in _DIGITS:
                i += 1
            # A literal immediately followed by '.' (e.g. "1.5") is not a
            # decimal integer literal; the '.' is rejected below as an unknown
            # character, which yields the required ValueError.
            tokens.append(_Token(_INT, int(text[start:i]), start))
            continue

        if ch == "(":
            tokens.append(_Token(_LPAREN, "(", i))
            i += 1
            continue

        if ch == ")":
            tokens.append(_Token(_RPAREN, ")", i))
            i += 1
            continue

        for op in _OPERATORS:
            if text.startswith(op, i):
                tokens.append(_Token(_OP, op, i))
                i += len(op)
                break
        else:
            raise ValueError(
                "invalid character %r at position %d" % (ch, i)
            )

    tokens.append(_Token(_END, None, n))
    return tokens


# ---------------------------------------------------------------------------
# Parser: builds a tuple-based AST, evaluated only after the full parse.
# ---------------------------------------------------------------------------
#
# AST node shapes:
#   ("num", value)
#   ("unary", op, operand)
#   ("binary", op, left, right)

_ADDITIVE = ("+", "-")
_MULTIPLICATIVE = ("*", "/", "//", "%")


class _Parser:
    def __init__(self, tokens):
        self._tokens = tokens
        self._index = 0

    # -- token helpers ------------------------------------------------------

    @property
    def _current(self):
        return self._tokens[self._index]

    def _advance(self):
        token = self._tokens[self._index]
        self._index += 1
        return token

    def _at_operator(self, operators):
        token = self._current
        return token.kind == _OP and token.value in operators

    # -- grammar rules ------------------------------------------------------

    def parse(self):
        node = self.parse_expr()
        token = self._current
        if token.kind != _END:
            raise ValueError(
                "unexpected %s at position %d"
                % (_describe(token), token.pos)
            )
        return node

    def parse_expr(self):
        node = self.parse_term()
        while self._at_operator(_ADDITIVE):
            op = self._advance().value
            node = ("binary", op, node, self.parse_term())
        return node

    def parse_term(self):
        node = self.parse_factor()
        while self._at_operator(_MULTIPLICATIVE):
            op = self._advance().value
            node = ("binary", op, node, self.parse_factor())
        return node

    def parse_factor(self):
        if self._at_operator(_ADDITIVE):
            op = self._advance().value
            # Unary operators are repeatable: "--3" == 3.
            return ("unary", op, self.parse_factor())
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self._at_operator(("**",)):
            self._advance()
            # Right-associative, and the exponent is a `factor`, so it may
            # carry its own unary sign: "2 ** -1" parses (and later fails
            # evaluation as a negative exponent).
            return ("binary", "**", base, self.parse_factor())
        return base

    def parse_atom(self):
        token = self._current
        if token.kind == _INT:
            self._advance()
            return ("num", token.value)
        if token.kind == _LPAREN:
            self._advance()
            if self._current.kind == _RPAREN:
                raise ValueError(
                    "empty parentheses at position %d" % token.pos
                )
            node = self.parse_expr()
            if self._current.kind != _RPAREN:
                raise ValueError(
                    "unbalanced parenthesis opened at position %d" % token.pos
                )
            self._advance()
            return node
        raise ValueError(
            "expected an operand but found %s at position %d"
            % (_describe(token), token.pos)
        )


def _describe(token):
