    if kind == "num":
        return node[1]

    if kind == "unary":
        operand = _evaluate_node(node[2])
        return -operand if node[1] == "-" else +operand

    op = node[1]
    left = _evaluate_node(node[2])
    right = _evaluate_node(node[3])

    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if op == "/":
        if right == 0:
            raise ZeroDivisionError("division by zero")
        return left / right
    if op == "//":
        if right == 0:
            raise ZeroDivisionError("integer division or modulo by zero")
        return left // right
    if op == "%":
        if right == 0:
            raise ZeroDivisionError("integer division or modulo by zero")
        return left % right
    # op == "**"
    if right < 0:
        raise ValueError("negative exponent is not supported")
    return left**right


# ---------------------------------------------------------------------------
# Public entry point
# ---------------------------------------------------------------------------


def evaluate(text):
    """Evaluate an arithmetic expression and return an int or a float.

    Raises ValueError for anything the grammar rejects and ZeroDivisionError
    for division or modulo by zero (including `//` and `%`).
    """
    if not isinstance(text, str):
        raise TypeError(
            "evaluate() expects a string, not %s" % type(text).__name__
        )

